/**
 * Recipe guards — regression tests for three failure modes that reached a feature branch
 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
 *
 * All three share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
 * wrong output that is only visible by opening the page.
 *
 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
 *
 *   2. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
 *      can silently reset a longhand the base declared earlier.
 *
 *   3. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
 *      declaration, and the padding does not apply at all.
 */
import { describe, expect, test } from 'vitest';
import theme from '../index';
import { components } from './index';
import { spacing } from '../foundation/spacing';

const SPACING_KEYS = Object.keys(spacing);

const SIZING_PROPS = new Set([
  'width',
  'height',
  'minWidth',
  'maxWidth',
  'minHeight',
  'maxHeight',
  'boxSize',
  'w',
  'h',
  'minW',
  'maxW',
  'minH',
  'maxH',
]);

/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);

type Found = { recipe: string; path: string; prop: string; value: string };

/** Recursively walk a style object, including nested media queries and pseudo-selectors. */
const walk = (node: unknown, recipe: string, path: string, hit: (f: Found) => void): void => {
  if (node === null || typeof node !== 'object') return;
  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${key}` : key;
    if (value !== null && typeof value === 'object') {
      walk(value, recipe, here, hit);
    } else if (typeof value === 'string') {
      hit({ recipe, path, prop: key, value });
    }
  }
};

/** baseStyle may be a plain object or a function of props (see zimmTextInput). */
const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
  const bs = recipe.baseStyle;
  if (typeof bs !== 'function') return bs;
  return (bs as (p: Record<string, unknown>) => unknown)({
    inverse: false,
    disabled: false,
    hasError: false,
    focused: false,
    filled: false,
    theme,
    colorMode: 'light',
  });
};

const collect = (): Found[] => {
  const found: Found[] = [];
  for (const [name, recipe] of Object.entries(components)) {
    const r = recipe as unknown as Record<string, unknown>;
    for (const section of [resolveBaseStyle(r), r.variants, r.sizes]) {
      walk(section, name, '', (f) => found.push(f));
    }
  }
  return found;
};

describe('recipe guards', () => {
  test('no sizing property uses a bare spacing-scale key', () => {
    const offenders = collect()
      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
      .map((f) => `${f.recipe}.${f.path || 'baseStyle'}.${f.prop}: '${f.value}'`);

    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
    expect(offenders).toEqual([]);
  });

  test('no compound shorthand contains a bare scale key', () => {
    const offenders = collect()
      .filter((f) => {
        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
        if (!f.value.includes(' ')) return false; // single token is fine
        // Split on whitespace outside var(...) and look for a bare scale key.
        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
        return parts.some((part) => SPACING_KEYS.includes(part));
      })
      .map((f) => `${f.recipe}.${f.path || 'baseStyle'}.${f.prop}: '${f.value}'`);

    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
    expect(offenders).toEqual([]);
  });

  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
    // base variants, and Header/ListMenu are partial overrides of components whose other
    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];

    const unexpected = Object.keys(components)
      .filter((name) => !INTENTIONAL_MERGES.includes(name))
      .filter((name) => {
        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
        const ourKeys = new Set(Object.keys(ours as object));
        // A key present after composition that we never declared came from the base theme.
        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
      });

    expect(unexpected).toEqual([]);
  });
});

import type { SystemStyleObject } from '@chakra-ui/react';

// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
const BORDER = {
  default: 'var(--zimm-color-border-forms)', // #707070 — Figma field/border/default
  hover: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/hover
  filled: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/filled
  focus: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/focus
  error: 'var(--zimm-color-status-error)', // #9c0000 — Figma field/border/error
} as const;

// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
// Figma does not spec inverse/hover or inverse/focus separately — same white as default.
const BORDER_INVERSE = {
  default: 'var(--zimm-color-text-inverse)',
  hover: 'var(--zimm-color-text-inverse)',
  filled: 'var(--zimm-color-text-inverse)',
  focus: 'var(--zimm-color-text-inverse)',
  error: 'var(--zimm-color-status-error-bg)', // #f98f8c
} as const;

// Figma: Textfield flush floated label — brand/font/size/250 (10px) / medium weight.
const LABEL_FLOATED_SIZE = 'var(--zimm-font-size-4xs)';
const LABEL_FLOATED_WEIGHT = 'var(--zimm-font-weight-medium)';
// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
const FIELD_CONTENT_HEIGHT = '36px';
// No opacity token in foundation yet — pending Tier 1 PR with UI-designer sign-off.
const OPACITY_DISABLED = 0.4;

const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';

/** State the component feeds in so the recipe can resolve the Figma colour cascade. */
export type ZimmTextInputStyleProps = {
  inverse?: boolean;
  disabled?: boolean;
  hasError?: boolean;
  focused?: boolean;
  /** Field has a value. Combined with `focused` this gives the floated-label state. */
  filled?: boolean;
};

const palette = (inverse?: boolean) => (inverse ? BORDER_INVERSE : BORDER);

/** Border colour precedence: disabled > error > focus > filled > default. */
export const resolveBorderColour = ({ inverse, disabled, hasError, focused, filled }: ZimmTextInputStyleProps) => {
  const p = palette(inverse);
  if (disabled) return p.default;
  if (hasError) return p.error;
  if (focused) return p.focus;
  if (filled) return p.filled;
  return p.default;
};

/** In error the hover colour holds (error > hover); otherwise it darkens to focus. */
export const resolveHoverBorderColour = (props: ZimmTextInputStyleProps) =>
  props.hasError ? resolveBorderColour(props) : palette(props.inverse).hover;

// Figma text/subtle = #666 for the floated/disabled label in light mode;
// text/inverse/subtle = #969696 in inverse mode.
export const resolveLabelColour = ({ inverse, disabled, focused, filled }: ZimmTextInputStyleProps) => {
  const floated = Boolean(focused || filled);
  if (disabled) return inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)';
  if (inverse) return floated ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-inverse)';
  return floated ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-text-default)';
};

export const ZimmTextInput = {
  parts: ['root', 'row', 'content', 'label', 'input', 'clearButton', 'helper', 'error'],
  baseStyle: (props: ZimmTextInputStyleProps): Record<string, SystemStyleObject> => {
    const { inverse, disabled, focused, filled } = props;
    const floated = Boolean(focused || filled);
    const textColour = inverse ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)';

    return {
      root: {
        display: 'block',
        width: '100%',
        opacity: disabled ? OPACITY_DISABLED : 1,
      },

      // Flush bottom-border row. Hover is a CSS pseudo-class, not JS state.
      row: {
        display: 'flex',
        alignItems: 'center',
        gap: 'xs',
        borderBottom: `var(--zimm-border-width-default) solid ${resolveBorderColour(props)}`,
        paddingTop: '2xs',
        paddingBottom: '2xs',
        // not in Figma — UX animation on border-colour state changes
        transition: `border-color ${MOTION}`,
        _hover: disabled ? undefined : { borderBottomColor: resolveHoverBorderColour(props) },
      },

      // Figma: content flex-[1_0_0] h-[36px]
      content: { flex: 1, position: 'relative', minHeight: FIELD_CONTENT_HEIGHT },

      label: {
        position: 'absolute',
        left: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: floated ? LABEL_FLOATED_WEIGHT : 'var(--zimm-font-weight-regular)',
        fontSize: floated ? LABEL_FLOATED_SIZE : 'var(--zimm-font-size-2xs)',
        lineHeight: floated ? undefined : 'var(--zimm-font-lineheight-2xs)',
        color: resolveLabelColour(props),
        top: floated ? '3xs' : '50%',
        transform: floated ? 'none' : 'translateY(-50%)',
        transition: `top ${MOTION}, transform ${MOTION}, font-size ${MOTION}, color ${MOTION}`,
        whiteSpace: 'nowrap',
      },

      input: {
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        width: '100%',
        height: 'var(--zimm-scale-l)', // 20px — var, not 'l': theme.sizes has no 'l' key
        background: 'transparent',
        border: 'none',
        outline: 'none',
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: 'var(--zimm-font-weight-regular)',
        fontSize: 'var(--zimm-font-size-2xs)',
        color: textColour,
        padding: 0,
        opacity: floated ? 1 : 0,
        cursor: disabled ? 'not-allowed' : 'text',
        transition: `opacity ${MOTION}`,
      },

      clearButton: {
        background: 'transparent',
        border: 'none',
        padding: 0,
        cursor: 'pointer',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        color: textColour,
        // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size
        // var, not 'xl': min-width/height resolve via theme.sizes (xl = 36rem), not theme.space
        minWidth: 'var(--zimm-scale-xl)',
        minHeight: 'var(--zimm-scale-xl)',
        // WCAG 2.2 AA SC 2.4.7 — visible focus state
        _focusVisible: {
          outline: inverse
            ? 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)'
            : 'var(--zimm-focus-ring)',
          outlineOffset: 'var(--zimm-focus-ring-offset-default)',
          boxShadow: 'none',
        },
      },

      helper: {
        marginTop: '2xs',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-3xs)',
        color: inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)',
      },

      error: {
        marginTop: '2xs',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-2xs)',
        fontStyle: 'normal',
        fontWeight: 'var(--zimm-font-weight-regular)',
        lineHeight: 'var(--zimm-font-lineheight-2xs)',
        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
      },
    };
  },
};

