// what customers actually render. See frozenFiles.md > Design System.
// (Upstream source: Handover tokens/typography.css.)
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
