// ============================ TEMPORARY PROOF BLOCK ============================
/** The pre-fix walk: reports the leaf key, so a responsive container hides the property. */
const oldWalk = (node: unknown, recipe: string, path: string, hit: (f: Found) => void): void => {
  if (node === null || typeof node !== 'object') return;
  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${key}` : key;
    if (value !== null && typeof value === 'object') {
      oldWalk(value, recipe, here, hit);
    } else if (typeof value === 'string') {
      hit({ recipe, path, prop: key, value });
    }
  }
};

const runNew = (style: unknown): Found[] => {
  const out: Found[] = [];
  walk(style, 'Bad', '', '', (f) => out.push(f));
  return out;
};
const runOld = (style: unknown): Found[] => {
  const out: Found[] = [];
  oldWalk(style, 'Bad', '', (f) => out.push(f));
  return out;
};
const sizingHits = (found: Found[]) => found.filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value));
const typoHits = (found: Found[]) => found.filter((f) => TYPOGRAPHY_PROPS.get(f.prop)?.has(f.value) ?? false);

describe('PROOF S3 — the four shapes from the table', () => {
  const shapes = {
    "width:'xl'": { g: { width: 'xl' } },
    "_hover:{boxSize:'2xs'}": { g: { _hover: { boxSize: '2xs' } } },
    "width:['xl','2xl']": { g: { width: ['xl', '2xl'] } },
    "width:{base:'xl'}": { g: { width: { base: 'xl' } } },
  };
  for (const [label, style] of Object.entries(shapes)) {
    test(`${label}`, () => {
      const before = sizingHits(runOld(style)).length;
      const after = sizingHits(runNew(style)).map(where);
      console.log(`  ${label.padEnd(24)} old=${before ? 'CAUGHT' : 'MISSED'}  new=${after.length ? 'CAUGHT' : 'MISSED'}  ${JSON.stringify(after)}`);
      expect(after.length).toBeGreaterThan(0);
    });
  }
});

describe('PROOF S3 — false-positive controls (must all report zero)', () => {
  const controls: Record<string, unknown> = {
    'chakra sizes map (all-breakpoint keys, legit inner values)': {
      md: { width: 'var(--zimm-scale-xl)', fontSize: 'var(--zimm-font-size-2xs)' },
      lg: { width: '100%', fontSize: 'var(--zimm-font-size-xs)' },
    },
    'sizes map with responsive inside it': { md: { width: ['100%', '50%'] } },
    'mixed object — breakpoint-shaped key + real prop is NOT responsive': { g: { md: '1px', fontSize: 'var(--zimm-font-size-2xs)' } },
    'width via var()': { g: { width: 'var(--zimm-scale-xl)' } },
    'width percentage': { g: { width: '100%' } },
    'width explicit rem': { g: { width: '1.5rem' } },
    'responsive width with real units': { g: { width: ['100%', '50%'] } },
    'responsive width with vars': { g: { width: { base: 'var(--zimm-scale-l)', md: 'var(--zimm-scale-xl)' } } },
    'padding IS space-resolved, bare key correct': { g: { padding: 'xl', gap: 'xs', marginTop: '2xs' } },
    'empty object is not a responsive container': { g: {} },
  };
  for (const [label, style] of Object.entries(controls)) {
    test(label, () => {
      const hits = [...sizingHits(runNew(style)), ...typoHits(runNew(style))].map(where);
      expect(hits).toEqual([]);
    });
  }
});

describe('PROOF S3 — real theme: zero offenders, entry count unchanged', () => {
  test('entry count identical to the pre-fix walk', () => {
    const oldCount = Object.entries(components).reduce((n, [name, recipe]) => {
      const r = recipe as unknown as Record<string, unknown>;
      let c = 0;
      for (const section of [resolveBaseStyle(r), r.variants, r.sizes]) oldWalk(section, name, '', () => c++);
      return n + c;
    }, 0);
    const newCount = collect().length;
    const recipeCount = Object.keys(components).length;
    console.log(`  entries old=${oldCount} new=${newCount}  recipes=${recipeCount}`);
    expect(newCount).toBe(oldCount);
  });

  test('the reattributed props differ from the pre-fix walk (the fix does something)', () => {
    const oldProps: string[] = [];
    const newProps: string[] = [];
    for (const [name, recipe] of Object.entries(components)) {
      const r = recipe as unknown as Record<string, unknown>;
      for (const section of [resolveBaseStyle(r), r.variants, r.sizes]) {
        oldWalk(section, name, '', (f) => oldProps.push(`${f.path}|${f.prop}`));
        walk(section, name, '', '', (f) => newProps.push(`${f.path}|${f.prop}`));
      }
    }
    const changed = newProps.filter((p, i) => p !== oldProps[i]);
    console.log(`  reattributed leaves: ${changed.length} of ${newProps.length}`);
    console.log(`  sample: ${JSON.stringify(changed.slice(0, 6))}`);
    expect(changed.length).toBeGreaterThan(0);
  });

  test('real theme still yields zero sizing and zero typography offenders', () => {
    console.log(`  sizing offenders     = ${JSON.stringify(sizingHits(collect()).map(where))}`);
    console.log(`  typography offenders = ${JSON.stringify(typoHits(collect()).map(where))}`);
    expect(sizingHits(collect()).map(where)).toEqual([]);
    expect(typoHits(collect()).map(where)).toEqual([]);
  });
});

describe('PROOF S4 — typography guard', () => {
  const violations: Record<string, unknown> = {
    "fontSize:'2xs' (wrong value: 10px not 14px)": { g: { fontSize: '2xs' } },
    "fontSize:'4xs' (emits nothing)": { g: { fontSize: '4xs' } },
    "fontSize:'md' (16px not 24px)": { g: { fontSize: 'md' } },
    "fontSize:'l' (spacing key, emits nothing)": { g: { fontSize: 'l' } },
    "fontSize:'3xl' (spacing key, emits nothing)": { g: { fontSize: '3xl' } },
    "lineHeight:'2xs' (emits nothing)": { g: { lineHeight: '2xs' } },
    "lineHeight:'m' (spacing key)": { g: { lineHeight: 'm' } },
    "letterSpacing:'footer' (emits nothing)": { g: { letterSpacing: 'footer' } },
    "letterSpacing:'xs' (emits nothing)": { g: { letterSpacing: 'xs' } },
    "responsive fontSize:['2xs','xs']": { g: { fontSize: ['2xs', 'xs'] } },
    "responsive fontSize:{base:'4xs'}": { g: { fontSize: { base: '4xs' } } },
  };
  for (const [label, style] of Object.entries(violations)) {
    test(`CAUGHT: ${label}`, () => {
      const hits = typoHits(runNew(style)).map(where);
      console.log(`  ${JSON.stringify(hits)}`);
      expect(hits.length).toBe(1);
    });
  }

  const legit: Record<string, unknown> = {
    'var(--zimm-font-size-2xs)': { g: { fontSize: 'var(--zimm-font-size-2xs)' } },
    'var(--zimm-font-lineheight-2xs)': { g: { lineHeight: 'var(--zimm-font-lineheight-2xs)' } },
    'var(--zimm-font-size-4xs)': { g: { fontSize: 'var(--zimm-font-size-4xs)' } },
    "lineHeight:'normal'": { g: { lineHeight: 'normal' } },
    "fontSize:'0.875rem'": { g: { fontSize: '0.875rem' } },
    "fontSize:'inherit'": { g: { fontSize: 'inherit' } },
    "lineHeight:'1.2'": { g: { lineHeight: '1.2' } },
    "textStyle:'body2'": { g: { textStyle: 'body2' } },
    "letterSpacing:'0'": { g: { letterSpacing: '0' } },
  };
  for (const [label, style] of Object.entries(legit)) {
    test(`NOT flagged: ${label}`, () => {
      expect(typoHits(runNew(style)).map(where)).toEqual([]);
    });
  }
});
