import { FONT_REGULAR } from './overrides/app/theme/foundation/fonts';
import { fontSizes, lineHeights, fontWeights } from './overrides/app/theme/foundation/typography';
import { zimmTokens } from './overrides/app/theme/foundation/zimmTokens';

const varOf = (name: string) => (zimmTokens as Record<string, string>)[name];

const CURRENT = {
  fontFamily: varOf('--zimm-font-family-body'),
  fontSize: varOf('--zimm-font-size-2xs'),
  fontStyle: 'normal',
  fontWeight: varOf('--zimm-font-weight-regular'),
  lineHeight: varOf('--zimm-font-lineheight-2xs'),
};

const EXPANDED = css({ textStyle: 'body2' })(theme) as Record<string, unknown>;

console.log('--- zimmTokens vars resolve to the same foundation constants body2 uses ---');
console.log('--zimm-font-family-body    ', JSON.stringify(varOf('--zimm-font-family-body')), '=== FONT_REGULAR ?', varOf('--zimm-font-family-body') === FONT_REGULAR);
console.log("--zimm-font-size-2xs       ", JSON.stringify(varOf('--zimm-font-size-2xs')), "=== fontSizes['2xs'] ?", varOf('--zimm-font-size-2xs') === fontSizes['2xs']);
console.log("--zimm-font-lineheight-2xs ", JSON.stringify(varOf('--zimm-font-lineheight-2xs')), "=== lineHeights['2xs'] ?", varOf('--zimm-font-lineheight-2xs') === lineHeights['2xs']);
console.log('--zimm-font-weight-regular ', JSON.stringify(varOf('--zimm-font-weight-regular')), '=== fontWeights.regular ?', varOf('--zimm-font-weight-regular') === fontWeights.regular);

console.log('\n--- css({textStyle: "body2"})(theme) expands to ---');
console.log(JSON.stringify(EXPANDED, null, 2));

console.log('\n--- property-by-property comparison ---');
const props = new Set([...Object.keys(CURRENT), ...Object.keys(EXPANDED)]);
let mismatch = 0;
for (const p of [...props].sort()) {
  const cur = (CURRENT as Record<string, unknown>)[p];
  const nxt = EXPANDED[p];
  const same = String(cur) === String(nxt);
  if (cur === undefined || nxt === undefined) {
    console.log(`  ${p.padEnd(14)} current=${JSON.stringify(cur)}  body2=${JSON.stringify(nxt)}  <-- present on only one side`);
  } else {
    if (!same) mismatch++;
    console.log(`  ${p.padEnd(14)} ${same ? 'IDENTICAL' : 'DIFFERS  '}  ${JSON.stringify(cur)}  vs  ${JSON.stringify(nxt)}`);
  }
}
console.log(`\nmismatches on shared properties: ${mismatch}`);
