// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
// rem, not px: this height participates in a rem-derived measurement, so it has to scale with
// the root font-size (WCAG 1.4.4 — see overrideStyling.md > Units). footer.ts's
// SIZE_SUBSCRIBE_SLOT (2.8125rem) documents itself as "36px content + 4px/4px padding + 1px
// border"; freezing the content height in px broke that derivation as soon as the root font-size
// moved — at 200% zoom the slot reached 90px while the field reached only 53px, so the slot
// over-reserved by ~37px. (Dead space, not clipping: the no-layout-shift guarantee held either
// way, which is why this is a correctness-of-derivation fix rather than a bug fix.) In rem the
// derivation holds at every zoom level: at 200%, 72 + 16 + 1 = 89px against a 90px slot, the 1px
// residue being the deliberately-px border.
// theme/components/ is Tier 2 (owner: UI designer) and SIZE_SUBSCRIBE_SLOT is already annotated
// PROVISIONAL pending Kiera — this value should ride along with that sign-off, not land silently.
const FIELD_CONTENT_HEIGHT = '2.25rem'; // 36px at the default 16px root

