// ============================ TEMPORARY PROOF BLOCK (S8/S11) ============================
import { css, toCSSVar } from '@chakra-ui/react';
import { ZimmTextInput } from './zimmTextInput';
import { zimmTokens } from '../foundation/zimmTokens';

// extendTheme does NOT build __cssMap — ChakraProvider does, via toCSSVar. Without this the
// css() expansion below silently passes every token through unresolved.
const runtimeTheme = toCSSVar(theme as never);
const tokens = zimmTokens as unknown as Record<string, string>;

/** Substitute every var(--zimm-*) with the value zimmTokens.ts declares for it. */
const deref = (v: unknown): unknown =>
  typeof v === 'string' ? v.replace(/var\((--zimm-[a-z0-9-]+)\)/gi, (m, n) => tokens[n] ?? m) : v;

const expandResolved = (o: Record<string, unknown>) => {
  const out = css(o)(runtimeTheme) as Record<string, unknown>;
  const res: Record<string, unknown> = {};
  for (const k of Object.keys(out).sort()) res[k] = deref(out[k]);
  return res;
};

const BEFORE_ERROR = {
  marginTop: '2xs',
  marginBottom: 0,
  marginInline: 0,
  fontFamily: 'var(--zimm-font-family-body)',
  fontSize: 'var(--zimm-font-size-2xs)',
  fontStyle: 'normal',
  fontWeight: 'var(--zimm-font-weight-regular)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
};

describe('PROOF S8 — error part computed output is unchanged', () => {
  for (const inverse of [false, true]) {
    test(`inverse=${inverse}`, () => {
      const after = (ZimmTextInput.baseStyle({ inverse }) as Record<string, Record<string, unknown>>).error;
      const beforeR = expandResolved({
        ...BEFORE_ERROR,
        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
      });
      const afterR = expandResolved(after);
      console.log(`BEFORE(inverse=${inverse}) = ${JSON.stringify(beforeR, null, 0)}`);
      console.log(`AFTER (inverse=${inverse}) = ${JSON.stringify(afterR, null, 0)}`);
      const keys = [...new Set([...Object.keys(beforeR), ...Object.keys(afterR)])].sort();
      for (const k of keys) {
        const same = String(beforeR[k]) === String(afterR[k]);
        console.log(`   ${same ? 'SAME    ' : 'CHANGED '} ${k.padEnd(14)} ${JSON.stringify(beforeR[k])} -> ${JSON.stringify(afterR[k])}`);
      }
      // Every property the old form declared must survive with the identical value.
      for (const k of Object.keys(beforeR)) expect(String(afterR[k])).toBe(String(beforeR[k]));
      // letterSpacing is the only addition, and it is a no-op (inherited value is `normal`).
      const added = Object.keys(afterR).filter((k) => !(k in beforeR));
      console.log(`   added: ${JSON.stringify(added)} = ${JSON.stringify(added.map((k) => afterR[k]))}`);
      expect(added).toEqual(['letterSpacing']);
      expect(String(afterR.letterSpacing)).toBe('0');
    });
  }
});

describe('PROOF S11 — FIELD_CONTENT_HEIGHT unit', () => {
  test('2.25rem === 36px at a 16px root, and the recipe still resolves', () => {
    const content = (ZimmTextInput.baseStyle({}) as Record<string, Record<string, unknown>>).content;
    console.log('content =', JSON.stringify(content));
    expect(content.minHeight).toBe('2.25rem');
    expect(parseFloat(String(content.minHeight)) * 16).toBe(36);
    const expanded = css(content)(runtimeTheme) as Record<string, unknown>;
    console.log('content expanded =', JSON.stringify(expanded));
    expect(expanded.minHeight).toBe('2.25rem');
  });

  test('the slot derivation now holds at 100% and 200% root font-size', () => {
    const SLOT_REM = 2.8125; // footer.ts SIZE_SUBSCRIBE_SLOT
    const CONTENT_REM = 2.25; // this file, post-fix
    const PADDING_REM = 0.25 * 2; // paddingTop/Bottom '2xs' = 0.25rem each
    const BORDER_PX = 1; // borderWidths.default — deliberately px
    for (const root of [16, 32]) {
      const slot = SLOT_REM * root;
      const field = CONTENT_REM * root + PADDING_REM * root + BORDER_PX;
      const oldField = 36 + PADDING_REM * root + BORDER_PX; // pre-fix: frozen 36px content
      console.log(
        `  root=${root}px  slot=${slot}px  field(rem)=${field}px  gap=${(slot - field).toFixed(2)}px` +
          `   |  field(px, pre-fix)=${oldField}px  gap=${(slot - oldField).toFixed(2)}px`
      );
      expect(Math.abs(slot - field)).toBeLessThanOrEqual(BORDER_PX);
    }
  });
});
